UPDATE waste_disposal
SET disposal_target = #{disposalTarget}, voucher_no = #{voucherNo}
WHERE id = #{id}

mapper.select:
SELECT w.*, ci.name AS chemical_name, uo.nickname AS operator_name FROM waste_disposal w LEFT JOIN chem_info ci ON w.chemical_id = ci.id LEFT JOIN sys_user uo ON w.operator_id = uo.id WHERE 1 = 1
AND w.code LIKE CONCAT('%', #{keyword}, '%')
AND w.status = #{status} ORDER BY w.id DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM waste_disposal w WHERE 1 = 1

    AND w.code LIKE CONCAT('%', #{keyword}, '%')

AND w.status = #{status}
